def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    result = []
    i = 0

    while i < len(nums):
        start = nums[i]
        # Look for consecutive numbers
        while i + 1 < len(nums) and nums[i + 1] == nums[i] + 1:
            i += 1
        end = nums[i]

        # If run is 3 or more consecutive numbers, use ".."
        if end - start + 1 >= 3:
            result.append(f"{start}..{end}")
        else:
            # Otherwise list each number individually
            for j in range(start, end + 1):
                result.append(str(j))

        i += 1

    return ",".join(result)
